function translateNode(root,lang){
 const omit='input,textarea,select,option,script,style,[contenteditable],[data-no-i18n],.app-pill';
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){
  if(node.parentElement?.closest(omit))continue;
  const key=(node.nodeValue||'').trim();
  if(!key)continue;
  const translated=marketingCatalog[key]?.[lang] || window.PF_PRODUCT_LOCALE?.t?.(key);
  if(translated && translated!==key)node.nodeValue=node.nodeValue.replace(key,translated);
 }
 for(const el of [root,...root.querySelectorAll('[placeholder],[aria-label],[title]')]){
  if(el.closest(omit))continue;
  for(const attr of ['placeholder','aria-label','title']){
   const key=el.getAttribute(attr);if(!key)continue;
   const translated=marketingCatalog[key]?.[lang]||window.PF_PRODUCT_LOCALE?.t?.(key);
   if(translated && translated!==key)el.setAttribute(attr,translated);
  }
 }
}
export function setupMarketingLocale(){
 const header=document.querySelector('header');if(!header)return;
 let select=document.getElementById('pf-marketing-language');
 if(!select){
  // Progressive enhancement for third-party integrations using this module.
  const label=document.createElement('label');label.className='pf-marketing-locale';
  select=document.createElement('select');select.id='pf-marketing-language';
  for(const [code,name] of Object.entries(languageNames))select.add(new Option(name,code));
  label.append(select);header.insertBefore(label,header.querySelector('nav'));
 }
 const lang=currentLanguage();select.value=lang;
 select.setAttribute('aria-label',marketingCatalog['Sprache wählen']?.[lang]||'Sprache wählen');
 select.addEventListener('change',()=>{
  const next=location.pathname+location.search+location.hash;
  location.assign('/auth/language/?language='+encodeURIComponent(select.value)+'&next='+encodeURIComponent(next));
 });
 document.documentElement.lang=lang;
 if(lang==='de')return;
 const title=marketingCatalog['PROMPTFINISHER by netstyle – Bessere Prompts für Microsoft Copilot']?.[lang];
 if(title)document.title=title;
 let busy=false;
 const apply=()=>translateNode(document.body,lang);
 apply();
 new MutationObserver(records=>{
  if(busy||!records.some(r=>r.type==='childList'||r.type==='characterData'))return;
  busy=true;queueMicrotask(()=>{try{apply()}finally{busy=false}});
 }).observe(document.body,{subtree:true,childList:true,characterData:true});
}

